<?php require_once __DIR__.'/includes/bootstrap.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM products WHERE id=? AND is_active=1");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);$pageTitle='محصول یافت نشد';include __DIR__.'/includes/header.php';echo '<main class="page-content container"><h1>محصول پیدا نشد.</h1></main>';include __DIR__.'/includes/footer.php';exit;}
$rv=$pdo->prepare("SELECT r.*,u.full_name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? AND r.is_approved=1 ORDER BY r.created_at DESC");$rv->execute([$id]);$reviews=$rv->fetchAll();$pageTitle=$p['name'].' | رُزآرا';include __DIR__.'/includes/header.php';?>
<main class="page-content container"><div class="detail-layout"><div><img src="<?=e($p['image'])?>" alt="<?=e($p['name'])?>"></div><div><small>رُزآرا / <?=e($p['category'])?></small><h1><?=e($p['name'])?></h1><div class="rating">★★★★★ <?=e($p['rating'])?></div><h2 class="price"><?=toman($p['price'])?></h2><p><?=nl2br(e($p['description']))?></p><p>موجودی: <?= (int)$p['stock']>0?'موجود':'ناموجود' ?></p><button class="add-cart" data-id="<?=$p['id']?>" data-name="<?=e($p['name'])?>" data-price="<?=$p['price']?>" data-image="<?=e($p['image'])?>">افزودن به سبد خرید</button><hr><h3>نظرات کاربران</h3><?php foreach($reviews as $r):?><p><b><?=e($r['full_name'])?></b> · <?=str_repeat('★',(int)$r['rating'])?><br><?=e($r['body'])?></p><?php endforeach;?><?php if(!$reviews):?><p>هنوز دیدگاهی برای این محصول ثبت نشده است.</p><?php endif;?>
<?php if(logged_in()):?><form method="post" action="api/review.php" class="field"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>ثبت دیدگاه شما</label><select name="rating"><option value="5">۵ ستاره</option><option value="4">۴ ستاره</option><option value="3">۳ ستاره</option><option value="2">۲ ستاره</option><option value="1">۱ ستاره</option></select><textarea name="body" required placeholder="دیدگاه خود را بنویسید..."></textarea><button class="primary-btn">ارسال دیدگاه</button></form><?php else:?><p class="notice">برای ثبت دیدگاه باید <a href="login.php">وارد حساب کاربری</a> شوید. مشاهده دیدگاه‌ها برای همه آزاد است.</p><?php endif;?></div></div></main>
